"""Сформировать расширенный релизный набор golden-кейсов."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PATH = ROOT / "evals/golden_cases.json"
cases = json.loads(PATH.read_text(encoding="utf-8"))
cases = [case for case in cases if not case["id"].startswith(("x-", "dialog-"))]


def add(case_id, question, answer, must, sources, *, severity="P0", holdout=None,
        forbidden=None, slots=None, products=None, action="answer", clarification=None,
        escalation=False, history=None, mode="both"):
    independent = severity == "P0" if holdout is None else holdout
    if escalation and "специалист" not in answer.lower():
        answer += " Нужен специалист."
    cases.append({
        "id": case_id,
        "case_set": "release_holdout" if independent else "release_dev",
        "independent_holdout": independent,
        "mode": mode,
        "severity": severity,
        "history": history or [],
        "question": question,
        "reference_answer": answer,
        "expected_slots": slots or {},
        "expected_products": [
            {"product_id": product, "configuration": configuration}
            for product, configuration in (products or {}).items()
        ],
        "expected_action": action,
        "must_include": must,
        "must_not_include": forbidden or [],
        "required_clarification_slot": clarification,
        "escalation": {"required": escalation, "reason": "Требуется специалист" if escalation else None},
        "sources": sources,
    })


