def dialog(case_id, question, answer, *, history=None, slots=None, products=None, action="answer", severity="P1", forbidden=None, clarification=None, escalation=False, holdout=False):
    add(case_id, question, answer, [], ["docs/contract.md"], severity=severity, holdout=holdout,
        forbidden=forbidden, slots=slots, products=products, action=action, clarification=clarification,
        escalation=escalation, history=history, mode="interactive")

